class Solution {
public:
    std::vector<int> successfulPairs(std::vector<int>& spells, std::vector<int>& potions, long long success) {
        std::sort(potions.begin(), potions.end());
        int m = potions.size();
        std::vector<int> ans;
        ans.reserve(spells.size());
        for (long long s : spells) {
            long long min_p = (success + s - 1) / s;
            auto it = std::lower_bound(potions.begin(), potions.end(), min_p);
            ans.push_back(potions.end() - it);
        }
        return ans;
    }
};

class Solution {
    public int[] successfulPairs(int[] spells, int[] potions, long success) {
        java.util.Arrays.sort(potions);
        int m = potions.length;
        int[] ans = new int[spells.length];
        for (int i = 0; i < spells.length; i++) {
            long s = spells[i];
            long minP = (success + s - 1) / s;
            int lo = 0, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (potions[mid] >= minP) hi = mid;
                else lo = mid + 1;
            }
            ans[i] = m - lo;
        }
        return ans;
    }
}

var successfulPairs = function(spells, potions, success) {
    potions.sort((a, b) => a - b);
    const m = potions.length;
    const ans = new Int32Array(spells.length);
    for (let i = 0; i < spells.length; i++) {
        const s = spells[i];
        const minP = Math.ceil(success / s);
        let lo = 0, hi = m;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (potions[mid] >= minP) hi = mid;
            else lo = mid + 1;
        }
        ans[i] = m - lo;
    }
    return Array.from(ans);
};
